"""Server-side immutable public protocol snapshot. Excludes signals/weights and live logs."""
import datetime,hashlib,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 dest=OUT/'protocol_publication_snapshot_v1';assert not dest.exists();dest.mkdir()
 state=json.loads((OUT/'state54.json').read_text());runs=[]
 for folder in sorted((OUT/'runs').glob('*')):
  if (folder/'result.json').exists():
   result=json.loads((folder/'result.json').read_text());runs.append({'run':folder.name,'status':'COMPLETE','iterations':result['iterations'],'checkpoint_sha256':result['checkpoint_sha256']})
  elif (folder/'curve.jsonl').exists():
   lines=(folder/'curve.jsonl').read_text().splitlines();last=json.loads(lines[-1]);runs.append({'run':folder.name,'status':'RUNNING','last_logged_iteration':last['iteration'],'elapsed_seconds':last['elapsed_seconds']})
 progress={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'PROTOCOL_REGISTERED_FORMAL_COMPARISON_RUNNING','planned_fits':12,'completed_fits':sum(r['status']=='COMPLETE' for r in runs),'runs':runs,'training_state_at_snapshot':state['status'],'heldout_evaluation_started':False,'accepted_research_directions':0,'overall_goal':'ACTIVE_NOT_ACHIEVED','postprocessing':'Automatic evaluation/report pipeline waits for all 12 fit checkpoint hashes to be sealed.'}
 (dest/'PROGRESS54_V1.json').write_text(json.dumps(progress,indent=2),encoding='utf-8')
 text=('# C54 protocol registration: jointly learned latent dynamics\n\nThe fixed-budget comparison is running. No heldout comparison or research-direction claim is available from this snapshot. The complete 40-fit C53 closure remains in the prior experiment directory.\n\n'+f"Snapshot UTC: {progress['utc']}. Completed fits: {progress['completed_fits']}/12. Planned: six native RP-GSSM fits of 10,000 updates, six native LGSSM EM fits of 200 iterations.\n\n"+'Data are generated by the pinned native linear generator, using paper-matched observation covariance. All signals, weights and arrays remain on authorized server storage; no result files are synchronized to the local workstation. See `PROTOCOL.md`, `REPRODUCE.md`, and `plan54_v1.json`. The qualified active evaluator is `scripts/evaluate54_v2.py`. The server automatically waits for the all-fit seal before readout fitting and heldout scoring.\n\nThis is baseline and mechanism qualification. It does not establish a new world-model method, a real-domain generalization result, or a publication-ready gap.\n')
 (dest/'CURRENT_PROGRESS54_V1.md').write_text(text,encoding='utf-8')
 sources=[p for p in sorted(ROOT.rglob('*')) if p.is_file() and 'outputs' not in p.relative_to(ROOT).parts and '__pycache__' not in p.relative_to(ROOT).parts and p.suffix in ['.md','.json','.py','.ps1']]
 selected=sources+[OUT/'preflight54.json',OUT/'QUALIFICATION54_V2.json',OUT/'attempt54_v2_state.json',dest/'PROGRESS54_V1.json',dest/'CURRENT_PROGRESS54_V1.md']
 records=[]
 for path in selected:
  rel=path.relative_to(ROOT).as_posix()
  if path.parent==dest:public=path.name
  else:public=rel
  b=path.read_bytes();b.decode('utf-8');assert len(b)<500000
  target=dest/'files'/public;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(b)
  records.append({'path':public,'bytes':len(b),'sha256':sha(b),'git_blob_sha1':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest(),'server_snapshot_file':str(target)})
 manifest={'utc':progress['utc'],'status':'IMMUTABLE_PROTOCOL_SNAPSHOT_NO_COMPARATIVE_RESULTS','files':records,'file_count':len(records),'bytes':sum(r['bytes'] for r in records),'excluded':'Raw signals, weights, optimizer states, arrays, private transport helpers, credentials, changing training logs.'}
 (dest/'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
 print(json.dumps({'snapshot':str(dest),'file_count':len(records),'bytes':manifest['bytes'],'manifest_sha256':sha((dest/'manifest.json').read_bytes()),'progress':progress}),flush=True)
if __name__=='__main__':main()
